package net.officefloor.hq.app.sheet;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{id}/policy-versions")
@Validated
public class PolicyVersionController {

    /**
     * What the screen is told about a policy version: its number, the date it is in force from (null when
     * always), the setting it changed and the value it set (null: none), and the count of the sheet's
     * claims whose policy version it is.
     */
    public record PolicyVersionView(int number, LocalDate from, String key, String value, long claims) {

        static PolicyVersionView of(PolicyVersionService.Counted counted) {
            PolicyVersion v = counted.version();
            return new PolicyVersionView(v.getNumber(), v.getFromDate(), v.getKey(), v.getValue(), counted.claims());
        }
    }

    private final PolicyVersionService service;

    public PolicyVersionController(PolicyVersionService service) {
        this.service = service;
    }

    /** The sheet's policy versions, oldest first. */
    @GetMapping
    public List<PolicyVersionView> list(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String id) {
        return service.versions(id).stream().map(PolicyVersionView::of).toList();
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/**
 * A version of the sheet's policy settings: made by a change to one of them, numbered from 1 in the
 * order made, with the value the change set (null: none). It is in force on its from-date and after;
 * one with no from-date is in force always.
 */
@Embeddable
public class PolicyVersion {

    @Column(name = "version_number", nullable = false)
    private int number;

    @Column(name = "setting_key", nullable = false)
    private String key;

    /** The date the change was recorded from; null when in force always. */
    @Column(name = "from_date")
    private LocalDate fromDate;

    /** The value the change set the setting to; null for none. */
    @Column(name = "setting_value")
    private String value;

    protected PolicyVersion() {
    }

    public PolicyVersion(int number, String key, LocalDate fromDate, String value) {
        this.number = number;
        this.key = key;
        this.fromDate = fromDate;
        this.value = value;
    }

    public int getNumber() {
        return number;
    }

    public String getKey() {
        return key;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public String getValue() {
        return value;
    }

    /** Whether the version is in force on a date: its from-date is on or before it, or it has none. */
    public boolean inForceOn(LocalDate date) {
        return fromDate == null || !fromDate.isAfter(date);
    }
}
package net.officefloor.hq.app.sheet;

import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Reads a sheet's policy versions with how many of its claims each is the policy version of. */
@Service
public class PolicyVersionService {

    /** A policy version with the count of the sheet's claims whose policy version it is. */
    public record Counted(PolicyVersion version, long claims) {
    }

    private final SheetService sheets;
    private final ClaimRepository claims;

    public PolicyVersionService(SheetService sheets, ClaimRepository claims) {
        this.sheets = sheets;
        this.claims = claims;
    }

    /**
     * The sheet's policy versions, oldest first, each with the count of its claims whose policy version
     * (the one in force on the claim's date) it is.
     */
    @Transactional
    public List<Counted> versions(String id) {
        Sheet sheet = sheets.load(id);
        Map<Integer, Long> counts = claims.findBySheetIdOrderByIdDesc(id).stream()
                .map(Claim::getDate)
                .filter(Objects::nonNull)
                .map(sheet::policyVersionOn)
                .collect(Collectors.groupingBy(Function.identity(), Collectors.counting()));
        return sheet.getPolicyVersions().stream()
                .map(v -> new Counted(v, counts.getOrDefault(v.getNumber(), 0L)))
                .toList();
    }
}
